cssCode:
.ticket-wrap {
  perspective: 1000px;
  width: 280px; height: 140px;
  display: flex; align-items: center; justify-content: center;
}
.ticket {
  width: 100%; height: 100%;
  position: relative;
  background: linear-gradient(135deg, #111, #222);
  border-radius: 15px;
  box-shadow: 0 15px 35px rgba(0,0,0,0.6);
  transform-style: preserve-3d;
  transition: transform 0.1s ease-out;
  overflow: hidden;
  display: flex; align-items: center; padding: 20px;
  box-sizing: border-box; cursor: pointer;
  border: 1px solid #333;
}
.ticket-glare {
  position: absolute; top: -50%; left: -50%;
  width: 200%; height: 200%;
  background: linear-gradient(105deg, transparent 20%, rgba(0, 255, 204, 0.4) 25%, rgba(255, 0, 127, 0.4) 50%, transparent 55%);
  mix-blend-mode: color-dodge;
  transition: transform 0.1s ease-out;
  pointer-events: none;
}
.ticket-content {
  z-index: 2; color: #fff; font-family: sans-serif;
  transform: translateZ(20px);
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'ticket-wrap';

const ticket = document.createElement('div');
ticket.className = 'ticket';

const glare = document.createElement('div');
glare.className = 'ticket-glare';

const content = document.createElement('div');
content.className = 'ticket-content';
content.innerHTML = '<h2 style="margin:0; font-size:24px;">VIP PASS</h2><p style="margin:5px 0 0 0; color:#aaa; font-size:12px;">MOTIONZYNC EXCLUSIVE</p>';

ticket.appendChild(glare);
ticket.appendChild(content);
wrap.appendChild(ticket);
c.appendChild(wrap);

wrap.addEventListener('pointermove', (e) => {
  const rect = wrap.getBoundingClientRect();
  const x = e.clientX - rect.left - rect.width / 2;
  const y = e.clientY - rect.top - rect.height / 2;
  ticket.style.transform = `rotateX(${-y * 0.2}deg) rotateY(${x * 0.2}deg)`;
  glare.style.transform = `translate(${x * 1.5}px, ${y * 1.5}px)`;
});
wrap.addEventListener('pointerleave', () => {
  ticket.style.transform = `rotateX(0deg) rotateY(0deg)`;
  glare.style.transform = `translate(0px, 0px)`;
});
